macro_rules! deps {
    () => {
        NFA!();
        DFA!();
    };
}

macro_rules! WhichCaptures {
    () => {
        deps!();
        # [doc = " A configuration indicating which kinds of"] # [doc = " [`State::Capture`](crate::nfa::thompson::State::Capture) states to include."] # [doc = ""] # [doc = " This configuration can be used with [`Config::which_captures`] to control"] # [doc = " which capture states are compiled into a Thompson NFA."] # [doc = ""] # [doc = " The default configuration is [`WhichCaptures::All`]."] # [derive (Clone , Copy , Debug)] pub enum WhichCaptures { # [doc = " All capture states, including those corresponding to both implicit and"] # [doc = " explicit capture groups, are included in the Thompson NFA."] All , # [doc = " Only capture states corresponding to implicit capture groups are"] # [doc = " included. Implicit capture groups appear in every pattern implicitly"] # [doc = " and correspond to the overall match of a pattern."] # [doc = ""] # [doc = " This is useful when one only cares about the overall match of a"] # [doc = " pattern. By excluding capture states from explicit capture groups,"] # [doc = " one might be able to reduce the memory usage of a multi-pattern regex"] # [doc = " substantially if it was otherwise written to have many explicit capture"] # [doc = " groups."] Implicit , # [doc = " No capture states are compiled into the Thompson NFA."] # [doc = ""] # [doc = " This is useful when capture states are either not needed (for example,"] # [doc = " if one is only trying to build a DFA) or if they aren't supported (for"] # [doc = " example, a reverse NFA)."] # [doc = ""] # [doc = " # Warning"] # [doc = ""] # [doc = " Callers must be exceedingly careful when using this"] # [doc = " option. In particular, not all regex engines support"] # [doc = " reporting match spans when using this option (for example,"] # [doc = " [`PikeVM`](crate::nfa::thompson::pikevm::PikeVM) or"] # [doc = " [`BoundedBacktracker`](crate::nfa::thompson::backtrack::BoundedBacktracker))."] # [doc = ""] # [doc = " Perhaps more confusingly, using this option with such an"] # [doc = " engine means that an `is_match` routine could report `true`"] # [doc = " when `find` reports `None`. This is generally not something"] # [doc = " that _should_ happen, but the low level control provided by"] # [doc = " this crate makes it possible."] # [doc = ""] # [doc = " Similarly, any regex engines (like [`meta::Regex`](crate::meta::Regex))"] # [doc = " should always return `None` from `find` routines when this option is"] # [doc = " used, even if _some_ of its internal engines could find the match"] # [doc = " boundaries. This is because inputs from user data could influence"] # [doc = " engine selection, and thus influence whether a match is found or not."] # [doc = " Indeed, `meta::Regex::find` will always return `None` when configured"] # [doc = " with this option."] None , }
    };
}

WhichCaptures!();